import type { CardHeader, Card, ProjectSnapshot } from '../../data/data_types'
import type { ActionDefinition } from '../../data/action_types'
import type {
    ActionSearchMatch, BackgroundGroup, SearchMatch, SearchOptions, SearchRegexpAgent, SearchResults,
} from './search_types'

const CONTEXT_RADIUS = 40
const ELLIPSIS = 'â€¦'
const ROOT_GROUP = '(root)'
const BODY_FIELD = 'body'

/** Thrown when a RegExp-mode query is not a valid regular expression. */
export class InvalidSearchPatternError extends Error {
    constructor(message: string) {
        super(message)
        this.name = 'InvalidSearchPatternError'
    }
}

interface MatchLocation {
    index: number
    length: number
}

interface Matcher {
    find(text: string): MatchLocation | null
}

interface HeaderField {
    field: string
    value: string
}

interface ActionSearchField {
    field: ActionSearchMatch['field']
    value: string
}

function createTextMatcher(query: string): Matcher {
    const needle = query.toLowerCase()

    return {
        find(text: string) {
            const index = text.toLowerCase().indexOf(needle)

            return index === -1 ? null : { index, length: query.length }
        },
    }
}

function createRegexpMatcher(query: string): Matcher {
    let expression: RegExp

    try {
        expression = new RegExp(query)
    } catch (error) {
        throw new InvalidSearchPatternError(error instanceof Error ? error.message : 'Invalid regular expression')
    }

    return {
        find(text: string) {
            const found = text.match(expression)

            return found?.index === undefined ? null : { index: found.index, length: found[0].length }
        },
    }
}

function createMatcher(query: string, options: SearchOptions): Matcher {
    return options.mode === 'regexp' ? createRegexpMatcher(query) : createTextMatcher(query)
}

function collectHeaderFields(header: CardHeader): HeaderField[] {
    const fields: HeaderField[] = []
    const scalarEntries: [string, string | null][] = [
        ['id', header.id],
        ['title', header.title],
        ['status', header.status],
        ['owner', header.owner],
        ['author', header.author],
        ['after', header.after],
        ['internalId', header.internalId],
    ]

    for (const [field, value] of scalarEntries) {
        if (value) fields.push({ field, value })
    }

    for (const entry of header.affects) fields.push({ field: 'affects', value: entry })
    for (const [key, value] of Object.entries(header.policy)) fields.push({ field: `policy.${key}`, value: value ? 'true' : 'false' })

    return fields
}

function buildContext(text: string, location: MatchLocation): string {
    const start = Math.max(0, location.index - CONTEXT_RADIUS)
    const end = Math.min(text.length, location.index + location.length + CONTEXT_RADIUS)
    const slice = text.slice(start, end).replace(/\s+/gu, ' ').trim()
    const prefix = start > 0 ? ELLIPSIS : ''
    const suffix = end < text.length ? ELLIPSIS : ''

    return `${prefix}${slice}${suffix}`
}

function matchCard(card: Card, matcher: Matcher, searchBody: boolean): SearchMatch | null {
    const headerFields = collectHeaderFields(card.header)

    for (const { field, value } of headerFields) {
        const location = matcher.find(value)
        if (location) {
            return { card, context: buildContext(value, location), field, path: card.path, source: 'header', title: card.header.title }
        }
    }

    if (searchBody) {
        const location = matcher.find(card.content)
        if (location) {
            return { card, context: buildContext(card.content, location), field: BODY_FIELD, path: card.path, source: 'body', title: card.header.title }
        }
    }

    return null
}

function collectActionFields(action: ActionDefinition): ActionSearchField[] {
    const fields: ActionSearchField[] = [
        { field: 'label', value: action.label },
        { field: 'description', value: action.description },
    ]
    if (action.prompt) fields.push({ field: 'text', value: action.prompt })
    if (action.command) fields.push({ field: 'text', value: action.command })

    return fields
}

function matchAction(action: ActionDefinition, matcher: Matcher): ActionSearchMatch | null {
    for (const { field, value } of collectActionFields(action)) {
        const location = matcher.find(value)
        if (location) return { action, context: buildContext(value, location), field, title: action.label }
    }

    return null
}

function folderName(path: string) {
    const name = path.split('/').filter((segment) => segment.length > 0).at(-1)
    if (!name) throw new Error(`Cannot group background folder without a name: ${path}`)

    return name
}

function backgroundGroupKey(path: string, workingFolder: string, specialFolderPaths: string[]): string {
    const normalized = path.replace(/\\/gu, '/')
    const specialFolder = specialFolderPaths
        .map((folder) => folder.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, ''))
        .find((folder) => normalized === folder || normalized.startsWith(`${folder}/`))
    if (specialFolder) return folderName(specialFolder)

    const prefix = `${workingFolder}/`
    const rest = normalized.startsWith(prefix) ? normalized.slice(prefix.length) : normalized
    const segments = rest.split('/')

    return segments.length > 1 ? segments[0] : ROOT_GROUP
}

function groupBackgroundMatches(matches: SearchMatch[], workingFolder: string, specialFolderPaths: string[]): BackgroundGroup[] {
    const groups: BackgroundGroup[] = []
    const byFolder = new Map<string, BackgroundGroup>()

    for (const match of matches) {
        const folder = backgroundGroupKey(match.path, workingFolder, specialFolderPaths)
        const existing = byFolder.get(folder)

        if (existing) {
            existing.matches.push(match)
            continue
        }

        const group: BackgroundGroup = { folder, matches: [match] }
        byFolder.set(folder, group)

import { Box, Chip, List, ListItemButton, ListItemText, Typography } from '@mui/material'
import type { ActionDefinition } from '../../../data/action_types'
import type {
    ActionSearchMatch, SearchMatch, SearchMode, SearchResults as SearchResultsData,
} from '../../../services/search/search_types'

interface SearchResultsProps {
    mode: SearchMode
    onActionSelect: (action: ActionDefinition) => void
    onSelect: (path: string) => void
    query: string
    results: SearchResultsData
}

function renderHighlightedContext(context: string, query: string, mode: SearchMode) {
    let index: number
    let matchedText: string

    if (mode === 'text') {
        index = context.toLowerCase().indexOf(query.toLowerCase())
        if (index === -1) return context

        matchedText = context.slice(index, index + query.length)
    } else {
        try {
            const match = new RegExp(query).exec(context)
            if (!match) return context

            index = match.index
            matchedText = match[0]
        } catch {
            return context
        }
    }

    const before = context.slice(0, index)
    const after = context.slice(index + matchedText.length)

    return (
        <span>
            {before}
            <Box component="mark" sx={{ bgcolor: 'warning.light', borderRadius: 0.25, color: 'warning.contrastText' }}>
                {matchedText}
            </Box>
            {after}
        </span>
    )
}

function renderMatch(match: SearchMatch, onSelect: (path: string) => void, query: string, mode: SearchMode) {
    const handleClick = () => onSelect(match.path)
    const context = renderHighlightedContext(match.context, query, mode)

    return (
        <ListItemButton dense key={match.path} onClick={handleClick}>
            <ListItemText
                primary={
                    <Box component="span" sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
                        <span>{match.title}</span>
                        <Chip color={match.source === 'header' ? 'primary' : 'default'} label={match.source} size="small" />
                    </Box>
                }
                secondary={<span>{match.path} â€” {context}</span>}
            />
        </ListItemButton>
    )
}

function renderActionMatch(
    match: ActionSearchMatch,
    onActionSelect: (action: ActionDefinition) => void,
    query: string,
    mode: SearchMode,
) {
    const handleClick = () => onActionSelect(match.action)
    const context = renderHighlightedContext(match.context, query, mode)

    return (
        <ListItemButton dense key={match.action.id} onClick={handleClick}>
            <ListItemText
                primary={
                    <Box component="span" sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
                        <span>{match.title}</span>
                        <Chip color="secondary" label="action" size="small" />
                    </Box>
                }
                secondary={<span>{match.field} - {context}</span>}
            />
        </ListItemButton>
    )
}

/** Renders grouped search results: active cards first, then background cards grouped by folder. */
export function SearchResults(props: SearchResultsProps) {
    const { mode, onActionSelect, onSelect, query, results } = props
    const hasAny = results.active.length > 0 || results.backgroundGroups.length > 0 || results.actions.length > 0

    if (!hasAny) {
        return (
            <Box sx={{ p: 2 }}>
                <Typography color="text.secondary" variant="body2">
                    No matches found.
                </Typography>
            </Box>
        )
    }

    return (
        <Box>
            {results.active.length > 0 ? (
                <Box>
                    <Typography color="text.secondary" sx={{ px: 2, pt: 1 }} variant="overline">
                        Active cards
                    </Typography>
                    <List dense disablePadding>
                        {results.active.map((match) => renderMatch(match, onSelect, query, mode))}
                    </List>
                </Box>
            ) : null}
            {results.backgroundGroups.map((group) => (
                <Box key={group.folder}>
                    <Typography color="text.secondary" sx={{ px: 2, pt: 1 }} variant="overline">
                        {group.folder}
                    </Typography>
                    <List dense disablePadding>
                        {group.matches.map((match) => renderMatch(match, onSelect, query, mode))}
                    </List>
                </Box>
            ))}
            {results.actions.length > 0 ? (
                <Box>
                    <Typography color="text.secondary" sx={{ px: 2, pt: 1 }} variant="overline">
                        Actions
                    </Typography>
                    <List dense disablePadding>
                        {results.actions.map((match) => renderActionMatch(match, onActionSelect, query, mode))}
                    </List>
                </Box>
            ) : null}
        </Box>
    )
}
